#!/usr/bin/env node
// Generates the TypeScript, Swift and Kotlin registries from registry/types.json (decision #12),
// plus an XCTest that pins every HealthKit raw value the registry uses to its SDK symbol.
//
//   node scripts/gen-registry.mjs           write the generated files
//   node scripts/gen-registry.mjs --check   fail if any generated file is missing or stale
import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, join, relative } from 'node:path';

import * as prettier from 'prettier';

import { healthKitEnums, healthKitIdentifiers } from './lib/catalogs.mjs';
import { IOS_FLOOR, ROOT, compareOSVersions, loadCheckedRegistry, swiftIdentifier } from './lib/registry.mjs';

const HEADER = 'Generated by scripts/gen-registry.mjs from registry/types.json. Do not edit.';

/** The string HealthKit knows an identifier by at runtime. */
const runtimeIdentifier = (ios) => ios.rawValue ?? ios.identifier;
const WORKOUT_IDENTIFIER = 'HKWorkoutTypeIdentifier';

export const OUTPUTS = {
  readme: join(ROOT, 'docs/supported-types.md'),
  typeMapping: join(ROOT, 'docs/workout-activities.md'),
  ts: join(ROOT, 'src/generated/registry.ts'),
  swift: join(ROOT, 'ios/Sources/CapacitorHealthPlugin/Generated/Registry.generated.swift'),
  swiftTest: join(ROOT, 'ios/Tests/CapacitorHealthPluginTests/Generated/RegistryRawValuesTests.generated.swift'),
  kotlin: join(ROOT, 'android/src/main/kotlin/com/caplugins/health/generated/Registry.kt'),
};

const q = (s) => JSON.stringify(s);
/** A Swift Double literal. */
const swiftNumber = (n) => (Number.isInteger(n) ? `${n}.0` : String(n));
const supportedValues = (set, platform) =>
  set[platform] ? set.values.filter((v) => set[platform].map[v] !== null && set[platform].map[v] !== undefined) : null;

// ---------------------------------------------------------------- TypeScript

const METRIC_ORDER = ['sum', 'avg', 'min', 'max', 'count', 'duration'];

/** HealthKit's aggregation style for a type: its own, or its first member's. */
const iosAggregation = (t, registry) =>
  t.ios.aggregation ?? registry.types.find((x) => x.id === t.ios.members?.[0])?.ios?.aggregation;

/**
 * aggregate() metrics a type serves on iOS: the ones the plugin computes itself (`ios.metrics`), else
 * those of its aggregation style.
 */
function iosMetrics(t, registry) {
  if (!t.ios) return null;
  if (t.ios.metrics) return METRIC_ORDER.filter((m) => t.ios.metrics.includes(m));
  const style = t.ios.aggregation ?? registry.types.find((x) => x.id === t.ios.members?.[0])?.ios?.aggregation;
  if (!style) return null;
  if (style === 'cumulative') return ['sum'];
  // A combined discrete id has no average: per-member averages can't be combined without their weights.
  return t.ios.members ? ['min', 'max'] : ['avg', 'min', 'max'];
}

const androidMetrics = (t) =>
  t.android?.aggregates ? METRIC_ORDER.filter((m) => t.android.aggregates[m] !== undefined) : null;

async function renderTypeScript(registry) {
  const units = Object.fromEntries(
    Object.entries(registry.units).map(([id, u]) => [
      id,
      { dimension: u.dimension, ios: Boolean(u.ios), android: Boolean(u.android) },
    ]),
  );
  const valueSets = Object.fromEntries(
    Object.entries(registry.valueSets).map(([name, set]) => [
      name,
      { values: set.values, ios: supportedValues(set, 'ios'), android: supportedValues(set, 'android') },
    ]),
  );
  const entries = Object.fromEntries(
    registry.types.map((t) => {
      const entry = { id: t.id, kind: t.kind, group: t.group };
      if (t.values) entry.values = t.values;
      if (t.unit) Object.assign(entry, { unit: t.unit, units: t.units });
      if (t.parts) {
        entry.parts = Object.fromEntries(
          Object.entries(t.parts).map(([name, p]) => [name, p.values ? { values: p.values } : {}]),
        );
      }
      if (t.fields) {
        entry.fields = Object.fromEntries(
          Object.entries(t.fields).map(([name, f]) => {
            const field = { type: f.type };
            if (f.values) field.values = f.values;
            field.ios = Boolean(f.ios);
            field.android = f.android ? (f.android.computed ? 'computed' : 'stored') : false;
            if (f.ios?.requiredOnWrite) field.requiredOnWriteIos = true;
            return [name, field];
          }),
        );
      }
      if (t.ios) {
        entry.ios = { minOS: t.ios.minOS, writable: t.ios.writable, time: t.ios.time ?? 'any' };
        if (t.ios.identifier) entry.ios = { identifier: runtimeIdentifier(t.ios), ...entry.ios };
        if (t.ios.derivedFrom) entry.ios.derivedFrom = t.ios.derivedFrom;
        if (t.ios.members) entry.ios.members = t.ios.members;
        if (t.ios.writeTo) entry.ios.writeTo = t.ios.writeTo;
        if (t.ios.aggregateOnly) entry.ios.aggregateOnly = true;
        if (t.ios.range) entry.ios.range = t.ios.range;
        const metrics = iosMetrics(t, registry);
        if (metrics) entry.ios.metrics = metrics;
      }
      if (t.android) {
        const a = t.android;
        entry.android = {
          record: a.record,
          time: a.time,
          readPermission: a.readPermission,
          writePermission: a.writePermission,
          writable: a.writable,
        };
        if (a.feature) entry.android.feature = a.feature;
        if (a.maxDurationDays) entry.android.maxDurationDays = a.maxDurationDays;
        if (a.aggregateOnly) entry.android.aggregateOnly = true;
        if (a.wholeNumber) entry.android.wholeNumber = true;
        const metrics = androidMetrics(t);
        if (metrics) entry.android.metrics = metrics;
      }
      return [t.id, entry];
    }),
  );

  const nutrients = Object.fromEntries(
    Object.entries(registry.nutrients ?? {}).map(([id, n]) => [
      id,
      {
        unit: n.unit,
        ios: n.ios ? runtimeIdentifier(n.ios) : null,
        android: n.android?.property ?? null,
        max: n.android?.max ?? null,
      },
    ]),
  );

  const activities = Object.fromEntries(
    Object.entries(registry.workoutActivities ?? {}).map(([id, a]) => [id, { ios: Boolean(a.ios), android: Boolean(a.android) }]),
  );

  const { anySegment = [], anyActivity = [], activities: segmentActivities = {} } = registry.workoutSegments ?? {};
  const segments = { anySegment, anyActivity, activities: segmentActivities };

  const idsOfKind = (kind) =>
    registry.types
      .filter((t) => t.kind === kind)
      .map((t) => q(t.id))
      .join(' | ') || 'never';

  const source = `// ${HEADER}

/** Every unified type id, in registry order. */
export const HEALTH_TYPES = ${JSON.stringify(registry.types.map((t) => t.id))} as const;

/**
 * A unified health data type. Which platforms support it, and how, is in {@link REGISTRY}.
 *
 * @since 0.1.0
 */
export type HealthType = (typeof HEALTH_TYPES)[number];

/**
 * Types whose samples are a number with a unit.
 *
 * @since 0.1.0
 */
export type QuantityHealthType = ${idsOfKind('quantity')};

/**
 * Types whose samples hold one value from a fixed set (flow level, test result, severity…).
 *
 * @since 0.1.0
 */
export type CategoryHealthType = ${idsOfKind('category')};

/**
 * Types whose samples have no value, only a time range (the event happened).
 *
 * @since 0.1.0
 */
export type EventHealthType = ${idsOfKind('event')};

export type RegistryKind = 'quantity' | 'category' | 'event' | 'special';
export type RegistryGroup =
  | 'reproductiveHealth'
  | 'symptoms'
  | 'activity'
  | 'vitals'
  | 'body'
  | 'sleep'
  | 'nutrition'
  | 'mindfulness'
  | 'other';

/** Every workout activity id, in registry order. */
export const WORKOUT_ACTIVITY_IDS = ${JSON.stringify(Object.keys(registry.workoutActivities ?? {}))} as const;

/**
 * A workout's activity type. Which platforms store it is in {@link WORKOUT_ACTIVITIES}.
 *
 * @since 0.3.0
 */
export type WorkoutActivity = (typeof WORKOUT_ACTIVITY_IDS)[number];

/** Every nutrient id, in registry order. */
export const NUTRIENT_IDS = ${JSON.stringify(Object.keys(registry.nutrients ?? {}))} as const;

/**
 * A nutrient of a nutrition entry. Which platforms store it is in {@link NUTRIENTS}.
 *
 * @since 0.3.0
 */
export type Nutrient = (typeof NUTRIENT_IDS)[number];

/**
 * A statistic \`aggregate()\` can compute.
 *
 * @since 0.1.0
 */
export type AggregateMetric = 'sum' | 'avg' | 'min' | 'max' | 'count' | 'duration';

export interface RegistryUnit {
  /** Units of one type share a dimension. */
  dimension: string;
  /** HealthKit has this unit. */
  ios: boolean;
  /** Health Connect has this unit. */
  android: boolean;
}

export interface RegistryValueSet {
  /** Unified values, in display order. */
  values: readonly string[];
  /** Values HealthKit can store, or \`null\` when the set has no HealthKit mapping. */
  ios: readonly string[] | null;
  /** Values Health Connect can store, or \`null\` when the set has no Health Connect mapping. */
  android: readonly string[] | null;
}

export interface RegistryNutrient {
  /** Canonical unit: \`g\` or \`kcal\`. */
  unit: string;
  /** HealthKit dietary quantity identifier, or \`null\` when HealthKit has none. */
  ios: string | null;
  /** \`NutritionRecord\` property, or \`null\` when Health Connect has none. */
  android: string | null;
  /** The largest amount Health Connect accepts, in \`unit\`; nutrition entries take it on both platforms. */
  max: number | null;
}

/** One child array of a session type (sleep stages, workout segments and laps). */
export interface RegistryPart {
  /** Value set of each child's type. */
  values?: string;
}

export interface RegistryField {
  type: 'boolean' | 'enum';
  /** Value set name, for enum fields. */
  values?: string;
  ios: boolean;
  /** \`computed\`: derived by the plugin on read, not stored on the record. */
  android: 'stored' | 'computed' | false;
  requiredOnWriteIos?: true;
}

export interface RegistryEntry {
  id: HealthType;
  kind: RegistryKind;
  group: RegistryGroup;
  /** Value set name of the main value (category types). */
  values?: string;
  /** Canonical unit and the units callers may ask for (quantity types). */
  unit?: string;
  units?: readonly string[];
  fields?: Readonly<Record<string, RegistryField>>;
  /** Child arrays of a session type, by sample property. */
  parts?: Readonly<Record<string, RegistryPart>>;
  ios?: {
    /** Absent for combined ids (\`members\`). */
    identifier?: string;
    minOS: string;
    writable: boolean;
    /** \`instant\`: start must equal end. \`interval\`: end must be at least a second after start. */
    time: 'any' | 'instant' | 'interval';
    /** Values HealthKit accepts, in the type's only unit. */
    range?: { min: number; max: number };
    derivedFrom?: HealthType;
    /** Combined id: the split ids it reads together (decision #14). */
    members?: readonly HealthType[];
    /** Combined id: where writes go unless a sample names a member. */
    writeTo?: HealthType;
    /** No samples of its own; only \`aggregate()\` serves it. */
    aggregateOnly?: true;
    /** \`aggregate()\` metrics HealthKit serves. */
    metrics?: readonly AggregateMetric[];
  };
  android?: {
    record: string;
    time: 'instant' | 'interval' | 'series';
    readPermission: string;
    writePermission: string;
    writable: boolean;
    feature?: string;
    maxDurationDays?: number;
    /** No readable records; only \`aggregate()\` serves it. */
    aggregateOnly?: true;
    /** The record stores a whole number. */
    wholeNumber?: true;
    /** \`aggregate()\` metrics Health Connect serves. */
    metrics?: readonly AggregateMetric[];
  };
}

export const UNITS: Readonly<Record<string, RegistryUnit>> = ${JSON.stringify(units)};

export const VALUE_SETS: Readonly<Record<string, RegistryValueSet>> = ${JSON.stringify(valueSets)};

export const REGISTRY: Readonly<Record<HealthType, RegistryEntry>> = ${JSON.stringify(entries)};

export const NUTRIENTS: Readonly<Record<Nutrient, RegistryNutrient>> = ${JSON.stringify(nutrients)};

/** Which platforms can store each workout activity type. */
export const WORKOUT_ACTIVITIES: Readonly<Record<WorkoutActivity, { ios: boolean; android: boolean }>> = ${JSON.stringify(activities)};

/**
 * Which segment types Health Connect lets a session of each activity hold (decision #67): every type for
 * an activity in \`anySegment\`, the \`anyActivity\` types for any activity, and an activity's own list.
 */
export const WORKOUT_SEGMENTS: Readonly<{
  anySegment: readonly WorkoutActivity[];
  anyActivity: readonly string[];
  activities: Readonly<Partial<Record<WorkoutActivity, readonly string[]>>>;
}> = ${JSON.stringify(segments)};
`;
  const config = (await prettier.resolveConfig(OUTPUTS.ts)) ?? {};
  return prettier.format(source, { ...config, parser: 'typescript' });
}

// ---------------------------------------------------------------- Swift

const SWIFT_MAX = 140; // SwiftLint warns above 150

/** `name(a, b)` on one line when it fits at `indent`, otherwise one argument per line. */
function swiftCall(name, args, indent) {
  const pad = ' '.repeat(indent);
  const flat = `${name}(${args.join(', ')})`;
  if (pad.length + flat.length <= SWIFT_MAX) return pad + flat;
  return `${pad}${name}(\n${args.map((a) => `${pad}    ${a}`).join(',\n')}\n${pad})`;
}

/** An array literal on one line when it fits after `prefix`, otherwise one item per line. */
function swiftArray(items, indent, prefix = '') {
  const pad = ' '.repeat(indent);
  const flat = `[${items.join(', ')}]`;
  if (pad.length + prefix.length + flat.length + 2 <= SWIFT_MAX) return flat;
  return `[\n${items.map((item) => `${pad}    ${item}`).join(',\n')}\n${pad}]`;
}

function swiftAvailability(minOS) {
  return compareOSVersions(minOS, IOS_FLOOR) > 0
    ? `{ if #available(iOS ${minOS}, *) { return true }; return false }`
    : null;
}

/** HKWorkoutSwimmingLocationType raw values (pinned by the generated XCTest). */
const SWIMMING_LOCATIONS = { pool: 1, openWater: 2 };

/** Category cases newer than the iOS floor: HealthKit raises an exception for them on older iOS. */
const NEWER_CASES = { HKCategoryValueSleepAnalysis: ['AsleepCore', 'AsleepDeep', 'AsleepREM'] };
/** Members of registered correlations: written through their correlation, never alone. */
const CORRELATION_MEMBERS = ['HKQuantityTypeIdentifierBloodPressureSystolic', 'HKQuantityTypeIdentifierBloodPressureDiastolic'];

/**
 * The HealthKit catalog's unregistered quantity and category identifiers, which `hk:` passthrough ids may write
 * (decision #59), with the raw values each category accepts on the iOS floor. Identifiers not listed are read-only.
 */
function passthroughTable(registry) {
  const registered = new Set([...registry.types.flatMap((t) => (t.ios?.identifier ? [t.ios.identifier] : [])), ...CORRELATION_MEMBERS]);
  const enums = healthKitEnums();
  const quantities = [];
  const categories = [];
  for (const x of healthKitIdentifiers()) {
    if (x.deprecated || registered.has(x.identifier)) continue;
    if (x.identifier.startsWith('HKQuantityTypeIdentifier')) quantities.push(x.identifier);
    if (!x.identifier.startsWith('HKCategoryTypeIdentifier')) continue;
    const cases = enums[x.notes.trim()];
    if (!cases) continue;
    const newer = NEWER_CASES[x.notes.trim()] ?? [];
    const values = [...new Set(Object.entries(cases).filter(([name]) => !newer.includes(name)).map(([, raw]) => raw))];
    categories.push([x.identifier, values.sort((a, b) => a - b)]);
  }
  return { quantities, categories };
}

function renderSwift(registry) {
  const passthrough = passthroughTable(registry);
  const sets = Object.entries(registry.valueSets)
    .filter(([, set]) => set.ios)
    .map(([name, set]) => {
      const raw = set.values.filter((v) => set.ios.map[v] !== null).map((v) => `(${q(v)}, ${set.ios.map[v]})`);
      const prefix = `${q(name)}: RegistryValueSet(`;
      return `        ${prefix}${swiftArray(raw, 8, prefix)})`;
    });

  const byId = new Map(registry.types.map((t) => [t.id, t]));
  const nutrients = Object.entries(registry.nutrients ?? {})
    .filter(([, n]) => n.ios)
    .map(([id, n]) => `        ${q(id)}: RegistryNutrient(identifier: ${q(runtimeIdentifier(n.ios))}, unit: ${q(n.unit)})`);
  // Where a written distance total goes unless the activity names another member (decision #68).
  const defaultDistance = byId.get('distance')?.ios?.writeTo;
  const activities = Object.entries(registry.workoutActivities ?? {})
    .filter(([, a]) => a.ios)
    .map(([id, a]) => {
      const args = [q(id), `raw: ${a.ios.raw}`];
      const availability = swiftAvailability(a.ios.minOS);
      if (availability) args.push(`isAvailable: ${availability}`);
      if (a.ios.indoor !== undefined) args.push(`indoor: ${a.ios.indoor}`);
      if (a.ios.swimmingLocation) args.push(`swimmingLocation: ${SWIMMING_LOCATIONS[a.ios.swimmingLocation]}`);
      if (a.ios.distance === false) args.push('distance: nil');
      else if (a.ios.distance && a.ios.distance !== defaultDistance) args.push(`distance: ${q(a.ios.distance)}`);
      return swiftCall('RegistryWorkoutActivity', args, 8);
    });
  const units = Object.entries(registry.units)
    .filter(([, u]) => u.ios)
    .map(([id, u]) => `        ${q(id)}: RegistryUnit(${q(u.ios)}${u.percent ? ', percent: true' : ''})`);

  const entries = registry.types
    .filter((t) => t.ios)
    .map((t) => {
      // A combined id authorizes and resolves through its write member (or first member).
      const identifier = runtimeIdentifier(t.ios.identifier ? t.ios : byId.get(t.ios.writeTo ?? t.ios.members[0]).ios);
      const args = [q(t.id), `.${t.kind}`, q(identifier), `minOS: ${q(t.ios.minOS)}`];
      const availability = swiftAvailability(t.ios.minOS);
      if (availability) args.push(`isAvailable: ${availability}`);
      if (!t.ios.writable) args.push('writable: false');
      if (t.ios.time === 'instant') args.push('instantOnly: true');
      if (t.ios.time === 'interval') args.push('intervalOnly: true');
      if (t.values) args.push(`valueSet: ${q(t.values)}`);
      if (t.unit) args.push(`unit: ${q(t.unit)}`, `units: [${t.units.map(q).join(', ')}]`);
      if (t.ios.derivedFrom) args.push(`derivedFrom: ${q(t.ios.derivedFrom)}`);
      const style = iosAggregation(t, registry);
      if (style) args.push(`aggregation: .${style === 'cumulative' ? 'cumulative' : 'discrete'}`);
      if (t.ios.metrics) args.push(`metrics: [${iosMetrics(t, registry).map(q).join(', ')}]`);
      if (t.ios.members) args.push(`members: [${t.ios.members.map(q).join(', ')}]`);
      if (t.ios.writeTo) args.push(`writeTo: ${q(t.ios.writeTo)}`);
      if (t.ios.aggregateOnly) args.push('aggregateOnly: true');
      if (t.ios.range) args.push(`range: ${swiftNumber(t.ios.range.min)}...${swiftNumber(t.ios.range.max)}`);
      const fields = Object.entries(t.fields ?? {})
        .filter(([, f]) => f.ios)
        .map(([name, f]) => {
          const fargs = [q(name), `key: ${q(f.ios.key)}`, `type: .${f.type === 'enum' ? 'enumeration' : 'boolean'}`];
          if (f.values) fargs.push(`valueSet: ${q(f.values)}`);
          if (f.ios.requiredOnWrite) fargs.push('requiredOnWrite: true');
          return swiftCall('RegistryMetadataField', fargs, 16).trim();
        });
      if (fields.length) args.push(`fields: [${fields.join(', ')}]`);
      return swiftCall('RegistryEntry', args, 8);
    });

  return `// ${HEADER}
// swiftlint:disable file_length type_body_length line_length

import Foundation

enum RegistryKind {
    case quantity, category, event, special
}

enum RegistryFieldType {
    case boolean, enumeration
}

/// A unit's HealthKit form. Unit ids are what apps pass; HealthKit parses \`ios\` with \`HKUnit(from:)\`.
struct RegistryUnit {
    let ios: String
    /// 0–100 across the bridge, 0–1 in HealthKit (decision #15).
    let percent: Bool

    init(_ ios: String, percent: Bool = false) {
        self.ios = ios
        self.percent = percent
    }
}

enum RegistryAggregation {
    case cumulative, discrete
}

struct RegistryValueSet {
    /// Unified values HealthKit can store, in display order.
    let values: [String]
    /// Unified value → HealthKit raw value. Values HealthKit can't store are absent.
    let rawValues: [String: Int]

    init(_ pairs: [(String, Int)]) {
        values = pairs.map { $0.0 }
        rawValues = Dictionary(uniqueKeysWithValues: pairs)
    }
}

/// A nutrient HealthKit stores as a dietary quantity type (decision #61).
struct RegistryNutrient {
    /// Runtime identifier of its \`HKQuantityTypeIdentifierDietary…\` type.
    let identifier: String
    /// Canonical unit id.
    let unit: String
}

/// A workout activity type (decision #62): its HealthKit raw value and the metadata that narrows it.
struct RegistryWorkoutActivity {
    let id: String
    let raw: UInt
    /// \`false\` when the running OS predates the case.
    let isAvailable: () -> Bool
    /// \`HKMetadataKeyIndoorWorkout\`: true matches and writes indoor; false matches absent or false and writes false.
    let indoor: Bool?
    /// \`HKWorkoutSwimmingLocationType\` raw value it matches and writes.
    let swimmingLocation: Int?
    /// The distance type a written distance total goes to; nil when the activity takes none (decision #68).
    let distance: String?

    init(
        _ id: String,
        raw: UInt,
        isAvailable: @escaping () -> Bool = { true },
        indoor: Bool? = nil,
        swimmingLocation: Int? = nil,
        distance: String? = ${q(defaultDistance ?? 'distanceWalkingRunning')}
    ) {
        self.id = id
        self.raw = raw
        self.isAvailable = isAvailable
        self.indoor = indoor
        self.swimmingLocation = swimmingLocation
        self.distance = distance
    }
}

struct RegistryMetadataField {
    let name: String
    /// Runtime metadata key. Differs from the symbol name for iOS 8/9 keys (T06 S7).
    let key: String
    let type: RegistryFieldType
    let valueSet: String?
    let requiredOnWrite: Bool

    init(_ name: String, key: String, type: RegistryFieldType, valueSet: String? = nil, requiredOnWrite: Bool = false) {
        self.name = name
        self.key = key
        self.type = type
        self.valueSet = valueSet
        self.requiredOnWrite = requiredOnWrite
    }
}

struct RegistryEntry {
    let typeId: String
    let kind: RegistryKind
    /// Runtime identifier string. Built from raw strings so newer identifiers compile on the iOS ${IOS_FLOOR} floor.
    let identifier: String
    let minOS: String
    /// \`false\` when the running OS predates the identifier.
    let isAvailable: () -> Bool
    let writable: Bool
    /// Start must equal end, or HealthKit rejects the save.
    let instantOnly: Bool
    /// End must be at least a second after start: HealthKit raises an exception below its minimum duration.
    let intervalOnly: Bool
    let valueSet: String?
    /// Canonical unit (quantity types).
    let unit: String?
    /// Units callers may ask for, canonical first.
    let units: [String]
    /// Set for types with no HealthKit object of their own (\`menstruationPeriod\`).
    let derivedFrom: String?
    /// How \`aggregate()\` combines samples (quantity types).
    let aggregation: RegistryAggregation?
    /// Combined id (decision #14): the ids it reads together. \`identifier\` is then the write member's.
    let members: [String]
    let writeTo: String?
    /// No samples of its own; only \`aggregate()\` serves it.
    let aggregateOnly: Bool
    /// Values HealthKit accepts, in the canonical unit; outside it HealthKit raises an exception.
    let range: ClosedRange<Double>?
    let fields: [RegistryMetadataField]
    /// \`aggregate()\` metrics the plugin computes itself (special types), instead of HealthKit statistics.
    let metrics: [String]

    var isQuantity: Bool { identifier.hasPrefix("HKQuantityTypeIdentifier") }
    var isCorrelation: Bool { identifier.hasPrefix("HKCorrelationTypeIdentifier") }

    init(
        _ typeId: String,
        _ kind: RegistryKind,
        _ identifier: String,
        minOS: String,
        isAvailable: @escaping () -> Bool = { true },
        writable: Bool = true,
        instantOnly: Bool = false,
        intervalOnly: Bool = false,
        valueSet: String? = nil,
        unit: String? = nil,
        units: [String] = [],
        derivedFrom: String? = nil,
        aggregation: RegistryAggregation? = nil,
        members: [String] = [],
        writeTo: String? = nil,
        aggregateOnly: Bool = false,
        range: ClosedRange<Double>? = nil,
        fields: [RegistryMetadataField] = [],
        metrics: [String] = []
    ) {
        self.typeId = typeId
        self.kind = kind
        self.identifier = identifier
        self.minOS = minOS
        self.isAvailable = isAvailable
        self.writable = writable
        self.instantOnly = instantOnly
        self.intervalOnly = intervalOnly
        self.valueSet = valueSet
        self.unit = unit
        self.units = units
        self.derivedFrom = derivedFrom
        self.aggregation = aggregation
        self.members = members
        self.writeTo = writeTo
        self.aggregateOnly = aggregateOnly
        self.range = range
        self.fields = fields
        self.metrics = metrics
    }
}

enum Registry {
    /// Every unified type id, in registry order, including types HealthKit doesn't have.
    static let allTypeIds: [String] = [
${registry.types.map((t) => `        ${q(t.id)}`).join(',\n')}
    ]

    static let units: [String: RegistryUnit] = [
${units.join(',\n')}
    ]

    /** The unit ids in table order, for picking the first unit that fits a passthrough quantity. */
    static let unitOrder: [String] = [${Object.entries(registry.units).filter(([, u]) => u.ios).map(([id]) => q(id)).join(', ')}]

    /** Unregistered quantity identifiers \`hk:\` passthrough ids may write (decision #59). */
    static let passthroughQuantities: Set<String> = ${
      passthrough.quantities.length ? `[\n${passthrough.quantities.map((id) => `        ${q(id)}`).join(',\n')}\n    ]` : '[]'
    }

    /** Unregistered category identifiers \`hk:\` passthrough ids may write, with the raw values HealthKit accepts. */
    static let passthroughCategories: [String: [Int]] = [
${passthrough.categories.map(([id, values]) => `        ${q(id)}: [${values.join(', ')}]`).join(',\n')}
    ]

    static let valueSets: [String: RegistryValueSet] = [
${sets.join(',\n')}
    ]

    /// Workout activity types HealthKit stores, in registry order (decision #62).
    static let workoutActivities: [RegistryWorkoutActivity] = [
${activities.join(',\n')}
    ]

    /// Nutrients HealthKit stores, by unified nutrient id.
    static let nutrients: [String: RegistryNutrient] = [
${nutrients.join(',\n')}
    ]

    static let entries: [RegistryEntry] = [
${entries.join(',\n')}
    ]

    static let byId: [String: RegistryEntry] = Dictionary(uniqueKeysWithValues: entries.map { ($0.typeId, $0) })
}
`;
}

function renderSwiftTest(registry) {
  /** Assertions grouped under one `#available` per version (floor first), as a function body. */
  const gated = (items) => {
    const byOS = new Map();
    for (const { minOS, args } of items) {
      const key = compareOSVersions(minOS, IOS_FLOOR) > 0 ? minOS : IOS_FLOOR;
      if (!byOS.has(key)) byOS.set(key, []);
      byOS.get(key).push(args);
    }
    return [...byOS.keys()]
      .sort(compareOSVersions)
      .map((os) => {
        const gatedOS = os !== IOS_FLOOR;
        const lines = byOS.get(os).map((args) => swiftCall('XCTAssertEqual', args, gatedOS ? 12 : 8));
        return gatedOS ? `        if #available(iOS ${os}, *) {\n${lines.join('\n')}\n        }` : lines.join('\n');
      })
      .join('\n');
  };
  const testFunction = (name, items) => `    func ${name}() {\n${gated(items)}\n    }`;
  const capitalize = (s) => s[0].toUpperCase() + s.slice(1);

  const functions = [];
  const seen = new Set();
  const identifiers = registry.types
    .filter((t) => t.ios?.identifier && !seen.has(t.ios.identifier) && seen.add(t.ios.identifier))
    .map((t) => {
      // The workout type's identifier is a plain string constant, not a member of an identifier type.
      if (t.ios.identifier === WORKOUT_IDENTIFIER) {
        return { minOS: t.ios.minOS, group: t.group, args: [WORKOUT_IDENTIFIER, q(WORKOUT_IDENTIFIER)] };
      }
      const { swiftType, member } = swiftIdentifier(t.ios.identifier);
      return { minOS: t.ios.minOS, group: t.group, args: [`${swiftType}.${member}.rawValue`, q(runtimeIdentifier(t.ios))] };
    });
  for (const group of [...new Set(identifiers.map((i) => i.group))]) {
    functions.push(
      testFunction(
        `test${capitalize(group)}Identifiers`,
        identifiers.filter((i) => i.group === group),
      ),
    );
  }

  const nutrientIdentifiers = Object.values(registry.nutrients ?? {})
    .filter((n) => n.ios)
    .map((n) => {
      const { swiftType, member } = swiftIdentifier(n.ios.identifier);
      return { minOS: n.ios.minOS, args: [`${swiftType}.${member}.rawValue`, q(runtimeIdentifier(n.ios))] };
    });
  if (nutrientIdentifiers.length) functions.push(testFunction('testNutrientIdentifiers', nutrientIdentifiers));

  const activityCases = new Map();
  for (const a of Object.values(registry.workoutActivities ?? {})) {
    if (a.ios) activityCases.set(a.ios.case, { minOS: a.ios.minOS, args: [`HKWorkoutActivityType.${a.ios.case}.rawValue`, String(a.ios.raw)] });
  }
  if (activityCases.size) {
    functions.push(
      testFunction('testWorkoutActivityRawValues', [
        ...activityCases.values(),
        { minOS: '10.0', args: ['HKWorkoutSwimmingLocationType.pool.rawValue', '1'] },
        { minOS: '10.0', args: ['HKWorkoutSwimmingLocationType.openWater.rawValue', '2'] },
      ]),
    );
  }

  for (const [name, set] of Object.entries(registry.valueSets)) {
    if (!set.ios) continue;
    const items = set.values
      .filter((v) => set.ios.map[v] !== null)
      .map((v) => ({
        minOS: set.ios.valueMinOS?.[v] ?? set.ios.minOS,
        args: [`${set.ios.enum}.${set.ios.cases?.[v] ?? v}.rawValue`, String(set.ios.map[v])],
      }));
    functions.push(testFunction(`test${capitalize(name)}RawValues`, items));
  }

  const keys = new Map();
  for (const t of registry.types) {
    for (const f of Object.values(t.fields ?? {})) if (f.ios) keys.set(f.ios.metadata, f.ios.key);
  }
  functions.push(
    testFunction(
      'testMetadataKeys',
      [...keys].map(([symbol, key]) => ({ minOS: IOS_FLOOR, args: [symbol, q(key)] })),
    ),
  );

  return `// ${HEADER}
// swiftlint:disable type_body_length

import HealthKit
import XCTest

/// Pins every raw string and number in the generated registry to the HealthKit symbol it stands for,
/// so a typo in registry/types.json fails here instead of at runtime.
final class RegistryRawValuesTests: XCTestCase {
${functions.join('\n\n')}
}
`;
}

// ---------------------------------------------------------------- Kotlin

function renderKotlin(registry) {
  const imports = new Set([
    'androidx.health.connect.client.aggregate.AggregateMetric',
    'androidx.health.connect.client.records.Record',
    'androidx.health.connect.client.records.metadata.Metadata',
    'java.time.Duration',
    'java.time.Instant',
    'java.time.ZoneOffset',
    'kotlin.reflect.KClass',
  ]);
  const recordImport = (cls) => imports.add(`androidx.health.connect.client.records.${cls}`);
  const constant = (cls, name) => {
    recordImport(cls);
    return `${cls}.${name}`;
  };

  const sets = Object.entries(registry.valueSets)
    .filter(([, set]) => set.android)
    .map(([name, set]) => {
      const { constants: cls, map, absent } = set.android;
      const pairs = set.values.filter((v) => map[v] !== null).map((v) => `${q(v)} to ${constant(cls, map[v])}`);
      const args = [`constants = mapOf(\n${pairs.map((p) => `                ${p},`).join('\n')}\n            )`];
      if (absent) args.push(`absent = ${constant(cls, absent)}`);
      return `        ${q(name)} to RegistryValueSet(\n${args.map((a) => `            ${a},`).join('\n')}\n        ),`;
    });

  const entries = registry.types
    .filter((t) => t.android)
    .map((t) => {
      const a = t.android;
      recordImport(a.record);
      const args = [
        `id = ${q(t.id)}`,
        `kind = RegistryKind.${t.kind.toUpperCase()}`,
        `record = ${a.record}::class`,
        `time = RecordTime.${a.time.toUpperCase()}`,
        `readPermission = ${q(a.readPermission)}`,
        `writePermission = ${q(a.writePermission)}`,
        `writable = ${a.writable}`,
      ];
      if (a.valueProperty) args.push(`valueProperty = ${q(a.valueProperty)}`);
      if (t.values) args.push(`valueSet = ${q(t.values)}`);
      if (t.unit) args.push(`unit = ${q(t.unit)}`, `units = listOf(${t.units.map(q).join(', ')})`);
      if (a.feature) {
        imports.add('androidx.health.connect.client.HealthConnectFeatures');
        args.push(`feature = HealthConnectFeatures.${a.feature}`);
      }
      if (a.maxDurationDays) args.push(`maxDuration = Duration.ofDays(${a.maxDurationDays})`);
      if (a.aggregates) {
        const metrics = METRIC_ORDER.filter((m) => a.aggregates[m]).map(
          (m) => `${q(m)} to ${a.record}.${a.aggregates[m]}`,
        );
        args.push(`aggregates = mapOf(${metrics.join(', ')})`);
      }
      if (a.aggregateOnly) args.push('aggregateOnly = true');
      if (a.wholeNumber) args.push('wholeNumber = true');
      const fields = Object.entries(t.fields ?? {})
        .filter(([, f]) => f.android)
        .map(([name, f]) => {
          const fa = f.android;
          const fargs = [`name = ${q(name)}`];
          if (fa.property) fargs.push(`property = ${q(fa.property)}`);
          if (fa.computed) fargs.push('computed = true');
          if (f.values) fargs.push(`valueSet = ${q(f.values)}`);
          if (fa.true) fargs.push(`whenTrue = ${constant(fa.constants, fa.true)}`);
          if (fa.false) fargs.push(`whenFalse = ${constant(fa.constants, fa.false)}`);
          if (fa.absent) fargs.push(`absent = ${constant(fa.constants, fa.absent)}`);
          return `                RegistryField(${fargs.join(', ')}),`;
        });
      if (fields.length) args.push(`fields = listOf(\n${fields.join('\n')}\n            )`);
      return `        RegistryEntry(\n${args.map((x) => `            ${x},`).join('\n')}\n        ),`;
    });

  // One adapter per quantity record with a plain value; series (T28) and special records are hand-coded.
  const adapted = new Set();
  const adapters = registry.types
    .filter((t) => t.kind === 'quantity' && t.android && !t.android.aggregateOnly && t.android.time !== 'series')
    .filter((t) => !adapted.has(t.android.record) && adapted.add(t.android.record))
    .map((t) => {
      const { record, time, valueProperty, wholeNumber } = t.android;
      recordImport(record);
      const cls = registry.units[t.unit].android.class;
      const cast = cls === 'Number' ? (wholeNumber ? '(value as Double).toLong()' : 'value as Double') : `value as ${cls}`;
      const instant = time === 'instant';
      const times = instant
        ? `RecordTimes(it.time, it.zoneOffset, it.time, it.zoneOffset)`
        : `RecordTimes(it.startTime, it.startZoneOffset, it.endTime, it.endZoneOffset)`;
      const timeArgs = instant
        ? ['time = t.start', 'zoneOffset = t.startOffset']
        : ['startTime = t.start', 'startZoneOffset = t.startOffset', 'endTime = t.end', 'endZoneOffset = t.endOffset'];
      const enumFields = Object.entries(t.fields ?? {}).filter(([, f]) => f.android?.property);
      for (const [name, f] of enumFields) {
        if (f.type !== 'enum') throw new Error(`${t.id}.${name}: adapters only handle enum fields`);
      }
      const args = [...timeArgs, 'metadata = metadata', `${valueProperty} = ${cast}`];
      args.push(...enumFields.map(([name, f]) => `${f.android.property} = fields.getValue(${q(name)})`));
      const lines = [
        `times = { r -> (r as ${record}).let { ${times} } }`,
        `value = { r -> (r as ${record}).${valueProperty} }`,
      ];
      if (enumFields.length) {
        const pairs = enumFields.map(([name, f]) => `${q(name)} to it.${f.android.property}`).join(', ');
        lines.push(`fields = { r -> (r as ${record}).let { mapOf(${pairs}) } }`);
      }
      lines.push(`build = { t, metadata, value, fields -> ${record}(${args.join(', ')}) }`);
      return `        ${record}::class to QuantityAdapter(\n${lines.map((l) => `            ${l},`).join('\n')}\n        ),`;
    });

  const seriesAdapters = registry.types
    .filter((t) => t.kind === 'quantity' && t.android?.time === 'series')
    .filter((t) => !adapted.has(t.android.record) && adapted.add(t.android.record))
    .map((t) => {
      const { record, valueProperty, wholeNumber } = t.android;
      recordImport(record);
      const cls = registry.units[t.unit].android.class;
      const cast = cls === 'Number' ? (wholeNumber ? '(it.second as Double).toLong()' : 'it.second as Double') : `it.second as ${cls}`;
      const args = [
        'startTime = t.start',
        'startZoneOffset = t.startOffset',
        'endTime = t.end',
        'endZoneOffset = t.endOffset',
        `samples = points.map { ${record}.Sample(time = it.first, ${valueProperty} = ${cast}) }`,
        'metadata = metadata',
      ];
      const lines = [
        `times = { r -> (r as ${record}).let { RecordTimes(it.startTime, it.startZoneOffset, it.endTime, it.endZoneOffset) } }`,
        `points = { r -> (r as ${record}).samples.map { it.time to it.${valueProperty} } }`,
        `build = { t, metadata, points -> ${record}(${args.join(', ')}) }`,
      ];
      return `        ${record}::class to SeriesAdapter(\n${lines.map((l) => `            ${l},`).join('\n')}\n        ),`;
    });

  // Nutrients (T39): a read and an aggregate per NutritionRecord property, and a builder naming every one, so the
  // compiler checks each property and metric.
  const hcNutrients = Object.entries(registry.nutrients ?? {}).filter(([, n]) => n.android);
  if (hcNutrients.length) recordImport('NutritionRecord');
  const nutrients = hcNutrients.map(
    ([id, n]) =>
      `        ${q(id)} to RegistryNutrient(${q(n.unit)}, read = { it.${n.android.property} }, aggregate = NutritionRecord.${n.android.aggregate}, max = ${Number(n.android.max).toFixed(1)}),`,
  );
  const nutritionArgs = hcNutrients.map(([id, n]) => {
    const cls = registry.units[n.unit].android.class;
    return `${n.android.property} = values[${q(id)}] as ${cls}?`;
  });

  const hcActivities = Object.entries(registry.workoutActivities ?? {}).filter(([, a]) => a.android);
  if (hcActivities.length) recordImport('ExerciseSessionRecord');
  const activities = hcActivities.map(([id, a]) => `        ${q(id)} to ExerciseSessionRecord.${a.android.constant},`);
  const { anySegment = [], anyActivity = [], activities: segmentActivities = {} } = registry.workoutSegments ?? {};
  const kotlinSet = (ids) => `setOf(${ids.map(q).join(', ')})`;
  const segmentLists = Object.entries(segmentActivities).map(([id, list]) => `            ${q(id)} to ${kotlinSet(list)},`);

  const units = Object.entries(registry.units)
    .filter(([, u]) => u.android)
    .map(([id, u]) => {
      const { class: cls, factory, accessor, scale } = u.android;
      let read;
      let build;
      if (cls === 'Number') {
        read = '{ (it as Number).toDouble() }';
        build = '{ it }';
      } else if (cls === 'Percentage') {
        imports.add('androidx.health.connect.client.units.Percentage');
        read = '{ (it as Percentage).value }';
        build = '{ Percentage(it) }';
      } else {
        imports.add(`androidx.health.connect.client.units.${cls}`);
        read = scale ? `{ (it as ${cls}).${accessor} / ${scale} }` : `{ (it as ${cls}).${accessor} }`;
        build = scale ? `{ ${cls}.${factory}(it * ${scale}) }` : `{ ${cls}.${factory}(it) }`;
      }
      return `        ${q(id)} to RegistryUnit(${q(u.dimension)}, read = ${read}, build = ${build}),`;
    });

  // connect-client 1.1.0 marks mindfulness sessions experimental; using them needs an explicit opt-in.
  const optIns = imports.has('androidx.health.connect.client.records.MindfulnessSessionRecord')
    ? ['androidx.health.connect.client.feature.ExperimentalMindfulnessSessionApi']
    : [];
  optIns.forEach((cls) => imports.add(cls));
  const fileOptIn = optIns.length
    ? `@file:OptIn(${optIns.map((cls) => `${cls.split('.').pop()}::class`).join(', ')})\n\n`
    : '';

  return `// ${HEADER}
${fileOptIn}package com.caplugins.health.generated

${[...imports]
  .sort()
  .map((i) => `import ${i}`)
  .join('\n')}

enum class RegistryKind { QUANTITY, CATEGORY, EVENT, SPECIAL }

enum class RecordTime { INSTANT, INTERVAL, SERIES }

/**
 * A unit's Health Connect form: [read] turns a record's unit object (or plain number) into a number in
 * this unit, [build] turns a number in this unit into what the record takes (a plain Double for Number).
 */
class RegistryUnit(
    val dimension: String,
    val read: (Any) -> Double,
    val build: (Double) -> Any,
)

/** Unified value → Health Connect constant. Values Health Connect can't store are absent. */
class RegistryValueSet(
    val constants: Map<String, Int>,
    /** The "not recorded" constant: reads map it to an absent field, writes without the field use it. */
    val absent: Int? = null,
)

class RegistryField(
    val name: String,
    /** Record property holding the value; null when [computed]. */
    val property: String? = null,
    /** Derived by the plugin on read, not stored on the record. */
    val computed: Boolean = false,
    val valueSet: String? = null,
    val whenTrue: Int? = null,
    val whenFalse: Int? = null,
    val absent: Int? = null,
)

class RegistryEntry(
    val id: String,
    val kind: RegistryKind,
    val record: KClass<out Record>,
    val time: RecordTime,
    val readPermission: String,
    val writePermission: String,
    val writable: Boolean,
    val valueProperty: String? = null,
    val valueSet: String? = null,
    /** Canonical unit (quantity types). */
    val unit: String? = null,
    /** Units callers may ask for, canonical first. */
    val units: List<String> = emptyList(),
    /** HealthConnectFeatures constant that must be available, if any. */
    val feature: Int? = null,
    /** Longest interval the record accepts (inclusive). */
    val maxDuration: Duration? = null,
    /** aggregate() metric → the record's AggregateMetric. */
    val aggregates: Map<String, AggregateMetric<*>> = emptyMap(),
    /** No readable records; only aggregate() serves it (decision #21). */
    val aggregateOnly: Boolean = false,
    /** The value property is a Long: writes reject fractions. */
    val wholeNumber: Boolean = false,
    val fields: List<RegistryField> = emptyList(),
)

/** A record's start and end; an instant record's are equal. */
class RecordTimes(val start: Instant, val startOffset: ZoneOffset?, val end: Instant, val endOffset: ZoneOffset?)

/**
 * One quantity record class, generated so the codec needn't hand-code it (T27): its times, its main value (a
 * unit object or number, for [RegistryUnit.read]), its enum fields by unified name, and its constructor, which
 * takes the value from [RegistryUnit.build] and the enum fields' constants.
 */
class QuantityAdapter(
    val times: (Record) -> RecordTimes,
    val value: (Record) -> Any,
    val fields: (Record) -> Map<String, Int> = { emptyMap() },
    val build: (RecordTimes, Metadata, Any, Map<String, Int>) -> Record,
)

/** A nutrient of a NutritionRecord (decision #61): its canonical unit, its property's unit object, the metric summing it. */
class RegistryNutrient(
    val unit: String,
    val read: (NutritionRecord) -> Any?,
    val aggregate: AggregateMetric<*>,
    /** The largest amount NutritionRecord accepts, in [unit]. */
    val max: Double,
)

/** One series record class (T28): its times, its points (time and value object), and its constructor. */
class SeriesAdapter(
    val times: (Record) -> RecordTimes,
    val points: (Record) -> List<Pair<Instant, Any>>,
    val build: (RecordTimes, Metadata, List<Pair<Instant, Any>>) -> Record,
)

object Registry {
    /** Every unified type id, in registry order, including types Health Connect doesn't have. */
    val allTypeIds: List<String> = listOf(
${registry.types.map((t) => `        ${q(t.id)},`).join('\n')}
    )

    /** Units Health Connect can hold, by unified unit id. */
    val units: Map<String, RegistryUnit> = mapOf(
${units.join('\n')}
    )

    /** Constants keep the value set's display order. */
    val valueSets: Map<String, RegistryValueSet> = mapOf(
${sets.join('\n')}
    )

    val entries: List<RegistryEntry> = listOf(
${entries.join('\n')}
    )

    val byId: Map<String, RegistryEntry> = entries.associateBy { it.id }

    /** Quantity records the codec reads and builds generically, by record class. */
    val adapters: Map<KClass<out Record>, QuantityAdapter> = mapOf(
${adapters.join('\n')}
    )

    /** Series records, read as one sample per point. */
    val seriesAdapters: Map<KClass<out Record>, SeriesAdapter> = mapOf(
${seriesAdapters.join('\n')}
    )

    /** Workout activity id → ExerciseSessionRecord exercise type (decision #62). */
    val workoutActivities: Map<String, Int> = mapOf(
${activities.join('\n')}
    )

    /**
     * Which segment types a session of each activity may hold, \`ExerciseSegment.isCompatibleWith\` (decision #67):
     * every type for an activity in [anySegment], the [anyActivity] types for any activity, and an activity's own list.
     */
    object WorkoutSegments {
        val anySegment: Set<String> = ${kotlinSet(anySegment)}
        val anyActivity: Set<String> = ${kotlinSet(anyActivity)}
        val activities: Map<String, Set<String>> = mapOf(
${segmentLists.join('\n')}
        )
    }

    /** NutritionRecord's nutrients, by unified nutrient id. */
    val nutrients: Map<String, RegistryNutrient> = mapOf(
${nutrients.join('\n')}
    )

    /** A NutritionRecord with [values] (nutrient id → Mass or Energy); nutrients not listed stay unset. */
    fun nutritionRecord(times: RecordTimes, metadata: Metadata, name: String?, mealType: Int, values: Map<String, Any>) =
        NutritionRecord(
            startTime = times.start,
            startZoneOffset = times.startOffset,
            endTime = times.end,
            endZoneOffset = times.endOffset,
            metadata = metadata,
            name = name,
            mealType = mealType,
${nutritionArgs.map((a) => `            ${a},`).join('\n')}
        )
}
`;
}

// ---------------------------------------------------------------- Type table (docs/supported-types.md)

const README_START = '<!-- registry-types:start -->';
const README_END = '<!-- registry-types:end -->';

/** The type table in docs/supported-types.md, between its markers; the rest of the file is left as it is. */
function renderReadme(registry, current) {
  if (!current?.includes(README_START) || !current.includes(README_END)) return current;
  const short = (permission) => permission.replace('android.permission.health.', '');
  const valuesOf = (t) => {
    if (t.unit) return t.units.map((u) => `\`${u}\``).join(', ');
    if (!t.values) return '';
    const set = registry.valueSets[t.values];
    return set.values
      .map((v) => {
        const ios = set.ios && set.ios.map[v] !== null;
        const android = set.android && set.android.map[v] !== null;
        const only = t.ios && t.android && ios !== android ? (ios ? ' (iOS)' : ' (Android)') : '';
        return `\`${v}\`${only}`;
      })
      .join(', ');
  };
  const rows = registry.types.map((t) => {
    const ios = t.ios?.members
      ? `combined: ${t.ios.members.map((m) => `\`${m}\``).join(' + ')}${t.ios.aggregateOnly ? ' (aggregate only)' : ''}`
      : t.ios
        ? `\`${t.ios.identifier.replace(/^HK(Category|Quantity|Correlation)TypeIdentifier/, '')}\` (iOS ${t.ios.minOS}+${t.ios.writable ? '' : ', read-only'}${t.ios.derivedFrom ? `, derived from \`${t.ios.derivedFrom}\`` : ''})`
        : '—';
    const android = t.android
      ? `\`${t.android.record}\`: \`${short(t.android.readPermission)}\` / \`${short(t.android.writePermission)}\`${t.android.feature ? ` (needs \`${t.android.feature}\`)` : ''}`
      : '—';
    return `| \`${t.id}\` | ${t.kind} | ${ios} | ${android} | ${valuesOf(t)} |`;
  });
  const table = [
    README_START,
    '<!-- Generated by scripts/gen-registry.mjs from registry/types.json. Do not edit. -->',
    '',
    '| Type | Kind | HealthKit | Health Connect record: read / write permission | Values or units |',
    '|---|---|---|---|---|',
    ...rows,
    '',
    README_END,
  ].join('\n');
  return (
    current.slice(0, current.indexOf(README_START)) +
    table +
    current.slice(current.indexOf(README_END) + README_END.length)
  );
}

// ---------------------------------------------------------------- 04-type-mapping §4b

const ACTIVITIES_START = '<!-- workout-activities:start -->';
const ACTIVITIES_END = '<!-- workout-activities:end -->';

/** 04-type-mapping's activity table, between its markers. */
function renderTypeMapping(registry, current) {
  if (!current?.includes(ACTIVITIES_START) || !current.includes(ACTIVITIES_END)) return current;
  const rows = Object.entries(registry.workoutActivities ?? {}).map(([id, a]) => {
    let ios = '—';
    if (a.ios) {
      ios = `\`${a.ios.case}\` (${a.ios.raw}${a.ios.minOS === '8.0' ? '' : `, iOS ${a.ios.minOS}`})`;
      if (a.ios.indoor !== undefined) ios += a.ios.indoor ? ' + indoor' : ' + not indoor';
      if (a.ios.swimmingLocation) ios += ` + ${a.ios.swimmingLocation}`;
    }
    const android = a.android ? `\`${a.android.constant.replace('EXERCISE_TYPE_', '')}\`` : '—';
    return `| \`${id}\` | ${ios} | ${android} | ${a.notes ?? ''} |`;
  });
  const table = [
    ACTIVITIES_START,
    '<!-- Generated by scripts/gen-registry.mjs from registry/types.json. Do not edit. -->',
    '',
    '| Unified | HealthKit `HKWorkoutActivityType` (raw) | Health Connect `EXERCISE_TYPE_*` | Notes |',
    '|---|---|---|---|',
    ...rows,
    '',
    ACTIVITIES_END,
  ].join('\n');
  return current.slice(0, current.indexOf(ACTIVITIES_START)) + table + current.slice(current.indexOf(ACTIVITIES_END) + ACTIVITIES_END.length);
}

// ---------------------------------------------------------------- main

export async function renderAll(registry = loadCheckedRegistry()) {
  return {
    [OUTPUTS.readme]: renderReadme(registry, existsSync(OUTPUTS.readme) ? readFileSync(OUTPUTS.readme, 'utf8') : null),
    [OUTPUTS.typeMapping]: renderTypeMapping(
      registry,
      existsSync(OUTPUTS.typeMapping) ? readFileSync(OUTPUTS.typeMapping, 'utf8') : null,
    ),
    [OUTPUTS.ts]: await renderTypeScript(registry),
    [OUTPUTS.swift]: renderSwift(registry),
    [OUTPUTS.swiftTest]: renderSwiftTest(registry),
    [OUTPUTS.kotlin]: renderKotlin(registry),
  };
}

async function main() {
  const check = process.argv.includes('--check');
  const files = await renderAll();
  const stale = [];
  for (const [path, content] of Object.entries(files)) {
    if (content === null) continue;
    const current = existsSync(path) ? readFileSync(path, 'utf8') : null;
    if (current === content) continue;
    if (check) stale.push(relative(ROOT, path));
    else {
      mkdirSync(dirname(path), { recursive: true });
      writeFileSync(path, content);
      console.log(`wrote ${relative(ROOT, path)}`);
    }
  }
  if (stale.length) {
    console.error(`Generated files are stale; run \`npm run registry:gen\`:\n  ${stale.join('\n  ')}`);
    process.exit(1);
  }
  if (check) console.log('Generated registry files are up to date.');
}

if (import.meta.url === `file://${process.argv[1]}`) {
  main().catch((error) => {
    console.error(error.message);
    process.exit(1);
  });
}
